#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long best = 0;
    for (int bit = 0; bit < 30; bit++) {
        long long run = 0;
        for (long long x : a) {
            if ((x >> bit) & 1) {
                run++;
                best = max(best, run);
            } else {
                run = 0;
            }
        }
    }
    cout << best << "\n";

    return 0;
}

